/**
 * Presentation-boundary translation for DB-seeded movement content.
 *
 * Audit 2026-09-15 (`/atleta/movimientos/[id]`): the Thruster detail printed
 * equipment "Barbell / Plates" and muscles "Quads, Glutes, Shoulders, Core,
 * Triceps" inside otherwise Spanish copy. That text is seeded into
 * `Movement.equipment` / `Movement.musclesWorked` (see `prisma/seed.ts`), not
 * hardcoded in `src/lib`, so the honest fix is two layers:
 *
 *  1. this mapper, so the athlete never reads English again, even on boxes
 *     whose rows were seeded months ago or generated by the AI content path;
 *  2. a seed/backfill translation, which is outside this change and is
 *     reported to the caller.
 *
 * Matching is accent- and case-insensitive and already-Spanish values pass
 * through untouched, so running this over translated rows is a no-op.
 */

function normalize(value: string): string {
  return value.trim().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
}

