function translate(dict: Record<string, string>, raw: string): string {
  const key = normalize(raw);
  return dict[key] ?? raw;
}

/** "Barbell" → "Barra"; "Barra" → "Barra". */
export function equipmentLabel(raw: string): string {
  return translate(EQUIPMENT_ES, raw);
}

/** "Quads" → "Cuádriceps"; "Cuádriceps" → "Cuádriceps". */
export function muscleLabel(raw: string): string {
  return translate(MUSCLE_ES, raw);
}

export function equipmentLabels(raw: readonly string[]): string[] {
  return raw.map(equipmentLabel);
}

export function muscleLabels(raw: readonly string[]): string[] {
  return raw.map(muscleLabel);
}

/**
 * Seeded descriptions leak model scaffolding ("Score: weight (kg). Tips RX:")
 * and half-English sentences. We cannot rewrite prose at runtime, but we can
 * strip the scaffolding that is unambiguously not athlete copy and translate
 * the fixed field labels the generator emits.
 */
export function cleanMovementDescription(raw: string | null): string | null {
  if (!raw) return null;
  const cleaned = raw
    // "Score: weight (kg)." — a data contract, not coaching copy.
    .replace(/\bScore:\s*[^.\n]*\.?/gi, "")
    .replace(/\bTips?\s+RX:\s*/gi, "Claves RX: ")
    .replace(/\bSetup:\s*/gi, "Montaje: ")
    .replace(/\bCues?:\s*/gi, "Clave: ")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return cleaned.length > 0 ? cleaned : null;
}
